    rect: vec4<f32>,
    uv: vec4<f32>,
    color: vec4<f32>,
    params: vec4<f32>
}

struct package_fluid_common_UiBuffer {
    header: vec4<f32>,
    quads: array<package_fluid_common_UiQuad>
